if __name__ == "__main__":
    _argv = sys.argv[1:]
    if _argv and _argv[0] == "read":
        raise SystemExit(reader_cli_main(_argv[1:]))
    if _argv and _argv[0] in ("serve", "web"):
        _argv = _argv[1:]
    raise SystemExit(main(_argv))  # webapp.main — serves the UI
